// Wish Granter / Исполнитель Желаний (Дар Тзинча, wdbc-1rno).
// Книга: автоманифестация любой психосилы (эPR9/9 Успехов), исполняющей
// чужое высказанное желание буквально — САМА манифестация не автоматизирована
// (какая психосила и как именно она исполняет желание — целиком отыгрыш за
// столом, движку нечего перепроверять). А вот расплата — "если манифестация
// помогает загадавшему больше, чем самому чемпиону (по усмотрению ГМа)" —
// после честного ответа ГМа реальный расчёт: 2d10+9 непоглощаемого урона в W.
const helped = await foundry.applications.api.DialogV2.confirm({
  window: { title: "Исполнитель Желаний" },
  content: "<p>Манифестация помогла загадавшему желание БОЛЬШЕ, чем самому чемпиону (решение ГМа)?</p>"
});
if (helped) {
  const roll = await new Roll("2d10+9").evaluate();
  await actor.update(woundLossUpdates(actor.system, roll.total));
  await ChatMessage.create(ChatMessage.applyRollMode({
    speaker,
    content: `<div class="wh-roll-result">
      <div class="roll-header">Исполнитель Желаний — ${actor.name}</div>
      <div class="roll-threshold">Желание помогло загадавшему больше — <b>${roll.total}</b> непоглощаемого урона в Раны.</div>
    </div>`,
    rolls: [roll]
  }, game.settings.get("core", "rollMode")));
} else {
  await ChatMessage.create(ChatMessage.applyRollMode({
    speaker,
    content: `<div class="wh-roll-result">
      <div class="roll-header">Исполнитель Желаний — ${actor.name}</div>
      <div class="roll-threshold">Желание исполнено буквой без ущерба чемпиону — расплаты нет.</div>
    </div>`
  }, game.settings.get("core", "rollMode")));
}
